const s=require('../../../../miniprogram/utils/service');Page({data:{busy:false,error:'',bound:false,demo:false,name:'',code:'',state:null,role:'',inviteCode:'',appetite:1},onShow(){this.load();},async load(){await s.run(this,async()=>{const c=await s.call();const me=c.state&&c.state.members.find(x=>x.id===c.uid);this.setData({bound:!c.unbound,state:c.state||null,role:c.role||'',demo:!!c.demo,inviteCode:c.inviteCode||'',appetite:me?me.appetite:1});});},onPullDownRefresh(){this.load().finally(()=>wx.stopPullDownRefresh());},field(e){this.setData({[e.currentTarget.dataset.key]:e.detail.value});},async create(){await s.run(this,()=>s.call('create',{name:this.data.name||'做饭的人'}));await this.load();},async join(){await s.run(this,()=>s.call('join',{code:this.data.code,name:this.data.name||'点菜的人'}));await this.load();},demo(){s.setMode('demo');this.load();},cloud(){s.setMode('cloud');this.setData({bound:false,demo:false});this.load();},guest(){s.setRole('guest');this.load();},cook(){s.setRole('cook');this.load();},async appetite(){await s.run(this,()=>s.call('appetite',{value:this.data.appetite}));await this.load();},copy(){wx.setClipboardData({data:this.data.inviteCode});},recipe(e){wx.navigateTo({url:'/pages/recipe/index'+(e.currentTarget.dataset.id?'?id='+e.currentTarget.dataset.id:'')});},history(){wx.navigateTo({url:'/pages/history/index'});},async subscribe(){await s.run(this,async()=>{const r=await s.subscribe();wx.showToast({title:'请按微信提示选择订阅',icon:'none'});});}});